/// <summary>
/// Converts container to string
/// </summary>
/// <param name = "c">container</param>
/// <param name = "sep">separator</param>
/// <returns>string</returns>
static str 1000 KCS_con2Str(container c, str 10 sep = ',')
{
    int         idx = 0;
    int         len = conlen(c);
    str  100    tmp;
    str 1000    retStr;
    ;
    while (idx < len)
    {
        idx += 1;
        if(retStr)
        {
            retStr += sep;
        }

        tmp = conpeek(c,idx);
        if (tmp != '0')
        {
            retStr += tmp;
        }
    }
    return retStr;
}

/// <summary>
/// Converts string to container    
/// </summary>
/// <param name = "_value">string</param>
/// <param name = "_sep">separtor</param>
/// <returns>container</returns>
static container KCS_str2con(str _value, str 10 _sep = ',')
{
    int length = strlen(_value);
    int i = 1;
    int j = strscan(_value, _sep, 1, length);
    container ret;

    void add2Ret(str _current)
    {
        ret += _current;
    }
    ;
    while (j)
    {
        add2Ret(substr(_value, i, j-i));
        i = j+1;
        j = strscan(_value, _sep, i, length);
    }
    add2Ret(substr(_value, i, length-i+1));
    return ret;
}
